  var ORDER = ['phones','computers','appliances','stationery','women','men','kids','shoes','print','cosmetics','furniture','grocery','building','auto','sport','jewelry','books'];
  var NICHES = ORDER.map(function(k){ var n=N[k]; return { key:k, uz:n.uz, ru:n.ru, en:n.en, icon:n.icon }; });

  function tr(x, lang){ if(x==null) return ''; if(typeof x==='string') return x; var i = lang==='ru'?1:(lang==='en'?2:0); return x[i]||x[0]; }
  function slugify(s){ return String(s).toLowerCase().replace(/[‘’'`ʻ"]/g,'').replace(/[^a-z0-9а-яё]+/g,'-').replace(/^-|-$/g,'').slice(0,60); }

  // tanlangan yo'nalishlar bo'yicha birlashtirilgan katalog
  function build(niches){
    var keys = ORDER.filter(function(k){ return niches && niches.indexOf(k) >= 0; });
    if(!keys.length) return null;
    var cats = [], products = [], banners = [], brands = {}, id = 1;
    keys.forEach(function(k){
      var n = N[k], catIds = [];
      n.cats.forEach(function(c){
        var cat = { id:c[0], slug:c[0], niche:k, name:{uz:c[1],ru:c[2],en:c[3]}, emoji:c[4], hue:c[5], count:0 };
        cats.push(cat); catIds.push(cat);
      });
      n.p.forEach(function(p, i){
        var cat = catIds[p[5]], nm = p[0];
        var name = (typeof nm==='string') ? {uz:nm,ru:nm,en:nm} : {uz:nm[0],ru:nm[1],en:nm[2]};
        var hue = (cat.hue + i*23) % 360;
        var disc = p[3] ? Math.round((1 - p[2]/p[3]) * 100) : 0;
        products.push({ id:id++, slug:slugify(name.en)+'-'+id, niche:k, cat:cat.id, catName:cat.name, name:name, brand:p[1], price:p[2], oldPrice:p[3]||0,
          discount:disc, kind:p[4], hue:hue, spec:p[6], tag:p[7], rating: 4.5 + ((i*7)%5)/10, reviews: 12 + (i*37)%180, image: img(p[4], hue) });
        cat.count++;
        brands[p[1]] = (brands[p[1]]||0) + 1;
      });
      n.banners.forEach(function(b){ banners.push({ niche:k, title:{uz:b[0][0],ru:b[0][1],en:b[0][2]}, text:{uz:b[1][0],ru:b[1][1],en:b[1][2]}, hue:b[2], cat:catIds[0].id }); });
    });
    return { niches:keys, categories:cats, products:products, banners:banners,
      brands: Object.keys(brands).map(function(b){ return { name:b, count:brands[b] }; }) };
  }

  var _cur;
  function current(){
    if(_cur !== undefined) return _cur;
    var n = (window.BRAND && window.BRAND.niches) || null;
    _cur = build(n);
    return _cur;
  }
  // tarjima lug'ati (uz -> [ru, en]) — mobil marketning gi18n qatlami uchun
  function i18n(){
    var D = {}, c = current(); if(!c) return D;
    c.categories.forEach(function(x){ D[x.name.uz] = [x.name.ru, x.name.en]; });
    c.products.forEach(function(x){ if(x.name.uz !== x.name.ru) D[x.name.uz] = [x.name.ru, x.name.en]; });
    c.banners.forEach(function(x){ D[x.title.uz] = [x.title.ru, x.title.en]; D[x.text.uz] = [x.text.ru, x.text.en]; });
    NICHES.forEach(function(x){ D[x.uz] = [x.ru, x.en]; });
    return D;
  }

  window.ICB_CATALOG = { NICHES:NICHES, build:build, current:current, svg:svg, img:img, tr:tr, i18n:i18n, kinds:Object.keys(ART) };
